import{useEffect,useState}from"react";import type{RouteConfig}from"@mercurjs/dashboard-sdk";import{Button,Card,Empty,Field,FormGrid,Message,Page,PageHeader,Status}from"../../spike/ui";import{Input}from"../../components/ui/input";import{Select}from"../../components/ui/select";import{Table,TableBody,TableCell,TableHead,TableHeader,TableRow}from"../../components/ui/table";declare const __BACKEND_URL__:string
export const config:RouteConfig={label:"الكوبونات",rank:61};type Product={id:string;title:string};const base=()=>String(__BACKEND_URL__||"http://localhost:9000").replace(/\/$/,"");async function api(p:string,i?:RequestInit){const r=await fetch(base()+p,{credentials:"include",...i,headers:{...(i?.body?{"content-type":"application/json"}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d}const tone=(s:string)=>s==='approved'?'success':s==='rejected'?'danger':'warning' as any
export default function Coupons(){const[products,setProducts]=useState<Product[]>([]),[rows,setRows]=useState<any[]>([]),[code,setCode]=useState(""),[percent,setPercent]=useState("10"),[scope,setScope]=useState<"product"|"store">("product"),[couponProduct,setCouponProduct]=useState(""),[msg,setMsg]=useState("");const load=async()=>{const[p,d]=await Promise.all([api('/vendor/products?limit=200&fields=id,title'),api('/vendor/spike/discounts')]);setProducts(p.products||[]);setRows((d.discounts||[]).filter((x:any)=>x.request_type==='coupon'))};useEffect(()=>{load().catch(e=>setMsg(e.message))},[]);const send=async()=>{if(!code.trim())return setMsg('اكتب كود الكوبون');if(scope==='product'&&!couponProduct)return setMsg('اختر المنتج');const pct=Math.max(1,Math.min(99,Number(percent)||0));await api('/vendor/spike/discounts',{method:'POST',body:JSON.stringify({request_type:'coupon',coupon_code:code,coupon_percentage:pct,target_type:scope,target_id:scope==='store'?'':couponProduct,product_title:scope==='store'?'كامل المتجر':products.find(p=>p.id===couponProduct)?.title})});setCode('');setCouponProduct('');setMsg('تم إرسال الكوبون للأدمن للموافقة');load()};const del=async(id:string)=>{if(!confirm('حذف الكوبون؟ إذا كان فعالاً سيتم إلغاؤه.'))return;try{await api(`/vendor/spike/discounts?id=${encodeURIComponent(id)}`,{method:'DELETE'});setMsg('تم حذف الكوبون');load()}catch(e:any){setMsg(e.message)}};return <Page><PageHeader title="الكوبونات" description="أنشئ كوبونًا لمنتج محدد أو لكل منتجات المتجر. الإدارة تراجع الطلب فقط."/>{msg&&<Message>{msg}</Message>}<Card><FormGrid><Field label="كود الكوبون"><Input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="SPIKE10"/></Field><Field label="النسبة %"><Input type="number" min="1" max="99" value={percent} onChange={e=>setPercent(e.target.value)}/></Field><Field label="يطبق على"><Select value={scope} onValueChange={v=>setScope(v as any)} options={[{value:'product',label:'منتج محدد'},{value:'store',label:'كامل المتجر'}]}/></Field>{scope==='product'&&<Field label="المنتج"><Select value={couponProduct} onValueChange={setCouponProduct} placeholder="اختر المنتج" options={products.map(p=>({value:p.id,label:p.title}))}/></Field>}</FormGrid><Button onClick={send}>إرسال الكوبون للموافقة</Button></Card><Card><h2>الكوبونات السابقة</h2>{rows.length?<Table><TableHeader><TableRow><TableHead>الكود</TableHead><TableHead>النسبة</TableHead><TableHead>النطاق</TableHead><TableHead>الحالة</TableHead><TableHead>الإجراء</TableHead></TableRow></TableHeader><TableBody>{rows.map(r=><TableRow key={r.id}><TableCell><b>{r.coupon_code}</b></TableCell><TableCell>{r.coupon_percentage}%</TableCell><TableCell>{r.target_type==='store'?'كامل المتجر':r.product_title||'منتج'}</TableCell><TableCell><Status tone={tone(r.status)}>{r.status==='pending'?'بانتظار الموافقة':r.status==='approved'?'مقبول':'مرفوض'}</Status></TableCell><TableCell><Button tone="danger" onClick={()=>del(r.id)}>حذف</Button></TableCell></TableRow>)}</TableBody></Table>:<Empty>لا توجد كوبونات بعد</Empty>}</Card></Page>}
